insert into knowledge_document (
    document_code, title, content, source_type, source_path, course_id, class_id,
    study_mode, version, permission_scope, status, chunk_count, error_message, indexed_at, created_at, updated_at
) values (
    #{documentCode}, #{title}, #{content}, #{sourceType}, #{sourcePath}, #{courseId}, #{classId},
    #{studyMode}, #{version}, #{permissionScope}, #{status}, #{chunkCount}, #{errorMessage}, #{indexedAt}, #{createdAt}, #{updatedAt}
)

mapper.select:
select 
from knowledge_document


        and (
            title like concat('%', #{keyword}, '%')
            or document_code like concat('%', #{keyword}, '%')
            or source_path like concat('%', #{keyword}, '%')
        )


        and status = #{status}


        and course_id = #{courseId}


        and study_mode = #{studyMode}


        and source_type = #{sourceType}


        and permission_scope = #{permissionScope}


order by id desc
